type Order = { id: number; total: number; status: "new" | "paid" }

// Chegarada (parametr va export qilinadigan natija) — annotatsiya
export function summarize(orders: Order[]): { count: number; revenue: number } {
    // Ichkarida — inference
    const paid = orders.filter(o => o.status === "paid")       // Order[]
    const revenue = paid.reduce((sum, o) => sum + o.total, 0)  // number
    return { count: paid.length, revenue }
}

const orders: Order[] = [
    { id: 1, total: 120_000, status: "paid" },
    { id: 2, total: 45_000, status: "new" },
    { id: 3, total: 80_000, status: "paid" },
]
console.log(summarize(orders))

