function timeAgo(from: Date, now: Date) {
    const sec = Math.round((now.getTime() - from.getTime()) / 1000)
    const units: [number, string][] = [[31536000, "yil"], [2592000, "oy"], [86400, "kun"], [3600, "soat"], [60, "daqiqa"]]
    for (const [size, name] of units) if (sec >= size) return `${Math.floor(sec / size)} ${name} oldin`
    return "hozirgina"
}

