function workdays(from: Date, to: Date) {
    let count = 0
    for (const d = new Date(from); d <= to; d.setUTCDate(d.getUTCDate() + 1)) {
        const day = d.getUTCDay()
        if (day !== 0 && day !== 6) count++
    }
    return count
}

