function formatDuration(totalSec: number): string {
    const h = Math.floor(totalSec / 3600), m = Math.floor((totalSec % 3600) / 60), s = totalSec % 60
    return [h && `${h} soat`, m && `${m} daqiqa`, s && `${s} soniya`].filter(Boolean).join(" ") || "0 soniya"
}
