function eachDay(from: string, to: string): string[] {
    const out: string[] = []
    for (let d = new Date(from + "T00:00:00Z"); d <= new Date(to + "T00:00:00Z"); d.setUTCDate(d.getUTCDate() + 1)) out.push(d.toISOString().slice(0, 10))
    return out
}
console.log(eachDay("2026-02-26", "2026-03-02"))

function parseUzDate(text: string): Date | null {
    const match = /^(\d{2})\.(\d{2})\.(\d{4})$/.exec(text.trim())
    if (!match) return null
    const [, dd, mm, yyyy] = match.map(Number)
    const date = new Date(Date.UTC(yyyy, mm - 1, dd))
    const real = date.getUTCDate() === dd && date.getUTCMonth() === mm - 1   // to'lib ketmaganmi?
    return real ? date : null
}

