for (const input of ["15.01.2026", "31.02.2026", "2026-01-15"]) {
    const d = parseUzDate(input)
    console.log(input.padEnd(12), d ? d.toISOString().slice(0, 10) : "noto'g'ri sana")
}

function countdown(now: Date, target: Date): string {
    let ms = target.getTime() - now.getTime()
    if (ms <= 0) return "boshlandi"
    const days = Math.floor(ms / 86_400_000)
    ms %= 86_400_000
    const hours = Math.floor(ms / 3_600_000)
    ms %= 3_600_000
    const minutes = Math.floor(ms / 60_000)
    return `${days} kun ${hours} soat ${minutes} daqiqa`
}

