console.log("Yangi yilgacha:", countdown(now, new Date("2027-01-01T00:00:00Z")))
console.log("O'tgan tadbir:", countdown(now, new Date("2026-12-01T00:00:00Z")))

function isoWeek(date: Date): number {
    const d = new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate()))
    const day = d.getUTCDay() || 7                 // yakshanba = 7
    d.setUTCDate(d.getUTCDate() + 4 - day)         // shu haftaning payshanbasiga o'tamiz
    const yearStart = Date.UTC(d.getUTCFullYear(), 0, 1)
    return Math.ceil(((d.getTime() - yearStart) / 86_400_000 + 1) / 7)
}

for (const iso of ["2026-01-01", "2026-01-05", "2026-12-31", "2027-01-03"]) {
    console.log(`${iso} → ${isoWeek(new Date(iso + "T00:00:00Z"))}-hafta`)
}

